import{c as l,$ as a,Q as o,j as i,g as e,o as r,n,m as d}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Клиентская база","description":"Практическое руководство по ведению клиентской базы мастерской в ОмниКрафт ЕРП — учет контактов, форматирование номеров телефонов, заметки и связь с заказ-нарядами.","frontmatter":{"title":"Клиентская база","description":"Практическое руководство по ведению клиентской базы мастерской в ОмниКрафт ЕРП — учет контактов, форматирование номеров телефонов, заметки и связь с заказ-нарядами.","datePublished":"2026-11-15","dateModified":"2026-11-25","order":13},"headers":[],"relativePath":"ru/docs/spaces/services/clients.md","filePath":"ru/docs/spaces/services/clients.md","lastUpdated":1795564800000}'),c={name:"ru/docs/spaces/services/clients.md"},g={id:"клиентская-база-реестр-заказчиков-и-контактные-данные",tabindex:"-1"};function p(h,t,m,u,f,b){const s=a("DocIcon");return o(),i("div",null,[e("h1",g,[r(s,{name:"about"}),t[0]||(t[0]=n(" Клиентская база: Реестр заказчиков и контактные данные ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#клиентская-база-реестр-заказчиков-и-контактные-данные","aria-label":'Permalink to "Клиентская база: Реестр заказчиков и контактные данные"'},"​",-1))]),t[2]||(t[2]=d('<p>В сервисном и ремонтном деле постоянные клиенты формируют фундамент финансовой стабильности цеха. Если серийное ремесленное производство может месяцами реализовывать готовую продукцию через обезличенные розничные продажи, то сервисный центр держится на долгосрочных связях: регулярном техническом обслуживании инструмента бригад, сезонной профилактике оборудования и повторных обращениях довольных заказчиков.</p><p>Когда контакты хранятся в записной книжке личного телефона мастера, теряются в десятках диалогов мессенджеров или фиксируются на бумажных карточках, мастерская регулярно несет скрытые потери. При смене сим-карты или потере смартфона база исчезает, индивидуальные требования заказчиков забываются, а история выполненных ремонтов оказывается утраченной.</p><p>В <strong>ОмниКрафт ЕРП</strong> рабочее пространство «Услуги» выносит клиентскую базу в самостоятельный централизованный инструмент. Вкладка <strong>«Клиенты»</strong> позволяет вести упорядоченный реестр контрагентов, моментально находить контактные данные и сохранять историю взаимодействий в единой связке с заказ-нарядами.</p><hr><h2 id="расположение-и-интерфеис-вкладки-«клиенты»" tabindex="-1">Расположение и интерфейс вкладки «Клиенты» <a class="header-anchor" href="#расположение-и-интерфеис-вкладки-«клиенты»" aria-label="Permalink to &quot;Расположение и интерфейс вкладки «Клиенты»&quot;">​</a></h2><p>В профиле пространства «Услуги» клиентская база занимает выделенную позицию в основном навигационном меню программы:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Мастерская] ➔ [Склад] ➔ [Услуги] ➔ [Заказы] ➔ [Клиенты] ➔ [Витрина] ➔ [ДДС] ➔ [Капитал] ➔ [Аналитика] ➔ [Настройки]</span></span></code></pre></div><p>Рабочий экран спроектирован для мгновенного доступа к контактным данным:</p><ul><li><strong>Верхняя панель управления:</strong> Включает строку живого поиска с кнопкой мгновенного сброса запроса и кнопку <strong>«Новый клиент»</strong>;</li><li><strong>Реестр карточек заказчиков:</strong> Компактный список клиентов, где каждая карточка отображает: <ul><li>Имя заказчика или название строительной/производственной организации;</li><li>Федеральный форматированный номер телефона для быстрой связи;</li><li>Служебные заметки и технологические особенности взаимодействия;</li><li>Кнопку редактирования параметров (иконка карандаша);</li><li>Кнопку безопасного удаления (иконка корзины).</li></ul></li></ul><hr><h2 id="пошаговое-руководство-регистрация-нового-заказчика" tabindex="-1">Пошаговое руководство: Регистрация нового заказчика <a class="header-anchor" href="#пошаговое-руководство-регистрация-нового-заказчика" aria-label="Permalink to &quot;Пошаговое руководство: Регистрация нового заказчика&quot;">​</a></h2><p>Создание карточки клиента выполняется в момент первого обращения заказчика в мастерскую или при оформлении входящего оборудования.</p><ol><li>Перейдите во вкладку <strong>«Клиенты»</strong> и нажмите кнопку <strong>«Новый клиент»</strong> в правом верхнем углу.</li><li>В открывшемся диалоговом окне укажите данные: <ul><li><strong>«Имя клиента»:</strong> ФИО частного лица, имя мастера или наименование компании (<em>«Алексей Воронов (ООО СтройМонтаж)»</em>);</li><li><strong>«Телефон»:</strong> Номер телефона заказчика. Программа автоматически применит маску форматирования номеров (<code>+7 900 123-45-67</code>), исключая ошибки ввода;</li><li><strong>«Заметки»:</strong> Практические детали сотрудничества (предпочитаемый мессенджер, адрес строительного объекта, особенности парка инструмента или индивидуальные скидки).</li></ul></li><li>Нажмите кнопку <strong>«Сохранить»</strong>.</li></ol><p>Новый заказчик моментально появится в списке и станет доступен для выбора при формировании заказ-нарядов.</p><div class="info custom-block"><p class="custom-block-title">Единая маска телефонных номеров</p><p>Программа автоматически нормализует вводимые телефоны к единому стандарту. Независимо от того, как мастер набрал номер — через восьмерку, семерку или без пробелов, — система отобразит аккуратную запись <code>+7 999 123-45-67</code>. Это исключает дублирование контактов в базе данных.</p></div><hr><h2 id="управление-базои-поиск-редактирование-и-мягкое-удаление" tabindex="-1">Управление базой: Поиск, редактирование и мягкое удаление <a class="header-anchor" href="#управление-базои-поиск-редактирование-и-мягкое-удаление" aria-label="Permalink to &quot;Управление базой: Поиск, редактирование и мягкое удаление&quot;">​</a></h2><p>По мере накопления сотен контактов ключевым требованием к реестру становится скорость навигации:</p><ul><li><strong>Поиск на лету:</strong> Введите первые буквы имени, цифры телефона или фрагмент заметки в поисковую строку. Система фильтрует реестр без задержек. Нажатие на крестик в правом краю поля мгновенно очищает фильтр.</li><li><strong>Редактирование карточки:</strong> Кликните по иконке карандаша в строке заказчика, чтобы изменить номер телефона, обновить служебные пометки или дополнить контактные данные.</li><li><strong>Мягкое удаление:</strong> При нажатии на иконку корзины программа покажет предупреждение: <em>«Вы действительно хотите удалить этого клиента?»</em>.</li></ul><div class="info custom-block"><p class="custom-block-title">Что сохраняется после удаления</p><p>Карточка скрывается из списка и поиска активного пространства. В ранее созданных заказ-нарядах остаётся имя заказчика, записанное при оформлении.</p></div><hr><h2 id="сквозная-интеграция-клиенты-➔-заказ-наряды" tabindex="-1">Сквозная интеграция: Клиенты ➔ Заказ-наряды <a class="header-anchor" href="#сквозная-интеграция-клиенты-➔-заказ-наряды" aria-label="Permalink to &quot;Сквозная интеграция: Клиенты ➔ Заказ-наряды&quot;">​</a></h2><p>Клиентская база в сервисе — это не изолированная записная книжка, а сквозной технологический справочник:</p><ol><li><strong>Мгновенный выбор при приеме наряда:</strong> При создании заказа во вкладке <strong>«Заказы»</strong> мастеру достаточно выбрать клиента из списка. Программа автоматически подставит имя контрагента в заголовок наряда.</li><li><strong>Снапшот имени (<code>client_name_snapshot</code>):</strong> При создании заказ-наряда система сохраняет текстовый слепок имени заказчика непосредственно в наряде. Если в будущем название компании контрагента изменится или мастер скорректирует карточку клиента, архивные документы сохранят именно то наименование, которое действовало в момент проведения ремонта.</li><li><strong>История гарантийных обязательств:</strong> Все открытые и завершенные работы привязаны к идентификатору заказчика, что позволяет мастеру за пару секунд поднять историю обслуживания конкретного узла при повторном визите.</li></ol><hr><h2 id="локальная-конфиденциальность-и-автономность" tabindex="-1">Локальная конфиденциальность и автономность <a class="header-anchor" href="#локальная-конфиденциальность-и-автономность" aria-label="Permalink to &quot;Локальная конфиденциальность и автономность&quot;">​</a></h2><p>Для реального ремесленного и сервисного бизнеса клиентская база представляет коммерческую тайну. Утечка номеров постоянных заказчиков к конкурентам способна нанести мастерской непоправимый ущерб.</p><ul><li><strong>Локальное хранение.</strong> Карточки клиентов хранятся в базе рабочего пространства на вашем компьютере.</li><li><strong>Доступ внешнего помощника.</strong> Подключённый помощник может читать список клиентов вместе с контактами и заметками. Изменение и удаление карточек требуют <a href="./../../global-settings">доверенного режима</a>.</li><li><strong>Отсутствие абонентской платы:</strong> Нет платы за количество внесенных контактов. В базе можно хранить как 50 постоянных клиентов, так и 10 000 заказчиков без ограничений тарифа;</li><li><strong>Автономность резервного копирования:</strong> Резервная копия базы создается напрямую через вкладку «Настройки» и может безопасно храниться на внешнем накопителе мастера.</li></ul><hr><h2 id="справочная-матрица-полеи-карточки-клиента" tabindex="-1">Справочная матрица полей карточки клиента <a class="header-anchor" href="#справочная-матрица-полеи-карточки-клиента" aria-label="Permalink to &quot;Справочная матрица полей карточки клиента&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Поле ввода</th><th style="text-align:left;">Назначение параметра</th><th style="text-align:left;">Формат и валидация</th><th style="text-align:left;">Рекомендация мастера по заполнению</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Имя клиента</strong></td><td style="text-align:left;">Основной идентификатор в нарядах</td><td style="text-align:left;">Текстовая строка (до 100 знаков)</td><td style="text-align:left;">Указывайте ФИО и компанию: <em>«Сергей Смирнов (Бригада 3)»</em></td></tr><tr><td style="text-align:left;"><strong>Телефон</strong></td><td style="text-align:left;">Прямая связь с заказчиком</td><td style="text-align:left;">Федеральная маска <code>+7 900 123-45-67</code></td><td style="text-align:left;">Проверяйте номер при приеме для согласования скрытых дефектов</td></tr><tr><td style="text-align:left;"><strong>Заметки</strong></td><td style="text-align:left;">Технологические и сервисные нюансы</td><td style="text-align:left;">Произвольный многострочный текст</td><td style="text-align:left;">Фиксируйте специфику оборудования и индивидуальные договоренности</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Цеховой совет мастера: Фиксируйте нюансы сразу при приемке</p><p>Никогда не надейтесь на память в потоке сервисных заказов. Если клиент просит <em>«вернуть старые шестерни в пакете для демонстрации руководству»</em> или <em>«звонить строго после 14:00»</em>, внесите эту информацию в поле заметок сразу при оформлении. Это исключит недопонимания при выдаче готового заказа и закрепит репутацию надежной мастерской.</p></div><hr><h2 id="разбор-внештатных-ситуации-troubleshooting" tabindex="-1">Разбор внештатных ситуаций (Troubleshooting) <a class="header-anchor" href="#разбор-внештатных-ситуации-troubleshooting" aria-label="Permalink to &quot;Разбор внештатных ситуаций (Troubleshooting)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если карточка клиента была случайно удалена из базы?</summary><div class="faq-content"><p>Карточка остаётся в базе пространства со скрытым статусом. Имя заказчика можно посмотреть в ранее оформленном наряде.</p></div></details><details class="faq-item"><summary class="faq-summary">Почему строка поиска не находит заказчика по фрагменту телефона?</summary><div class="faq-content"><p>Поисковый фильтр сопоставляет цифры номера без учета скобок и дефисов. Введите 4–5 последних цифр номера телефона подряд (например, <code>4567</code>) — программа мгновенно отфильтрует карточку заказчика.</p></div></details><details class="faq-item"><summary class="faq-summary">Исказит ли редактирование контактов клиента старые гарантийные акты?</summary><div class="faq-content"><p>Нет. При закрытии каждого заказ-наряда система сохраняет несгораемый снимок наименования клиента (<code>client_name_snapshot</code>). Любые последующие правки реквизитов применятся только к новым заказам, не затронув историческую документацию.</p></div></details></div>',35))])}const v=l(c,[["render",p]]);export{y as __pageData,v as default};
